            </div>
          </div>
        </section>

        {/* Videos Grid */}
        <section id="videos-grid" className="py-16 bg-neo-bg">
          <div className="container mx-auto px-4 md:px-6">
            <AnimatePresence mode="wait">
              {/* Affichage filtré par catégorie unique */}
              {filteredVideos ? (
                <motion.div
                  key={selectedType || "filtered"}
                  initial="hidden"
                  animate="visible"
